SELECT dept_name, budget_bucket, min_budget, bangkok_count FROM (SELECT dept_name, CASE WHEN budget >= 3491000 THEN 'high' WHEN budget >= 1121000 THEN 'mid' ELSE 'low' END AS budget_bucket, MIN(budget) AS min_budget, COUNT(CASE WHEN location = 'Bangkok' THEN 1 END) AS bangkok_count FROM departments WHERE budget <= 1920000 GROUP BY dept_name, CASE WHEN budget >= 3491000 THEN 'high' WHEN budget >= 1121000 THEN 'mid' ELSE 'low' END) AS x WHERE bangkok_count < 8 ORDER BY min_budget DESC, 2 DESC, dept_name LIMIT 50
